/**\n * Theme Configuration for IPTV Android TV App\n * Jetpack Compose Theme setup with color scheme and typography\n * Optimized for Android TV viewing\n */\n\npackage com.example.iptvapp.ui.theme\n\nimport androidx.compose.foundation.background\nimport androidx.compose.foundation.isSystemInDarkMode\nimport androidx.compose.material3.ColorScheme\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.Shapes\nimport androidx.compose.material3.Typography\nimport androidx.compose.runtime.Composable\nimport androidx.compose.runtime.CompositionLocalProvider\nimport androidx.compose.runtime.compositionLocalOf\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.text.TextStyle\nimport androidx.compose.ui.text.font.Font\nimport androidx.compose.ui.text.font.FontFamily\nimport androidx.compose.ui.text.font.FontStyle\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.unit.dp\nimport androidx.compose.ui.unit.sp\n\n// ==================== CUSTOM SPACING ====================\ndata class Spacing(\n    val xs: dp = 4.dp,\n    val sm: dp = 8.dp,\n    val md: dp = 12.dp,\n    val lg: dp = 16.dp,\n    val xl: dp = 24.dp,\n    val xxl: dp = 32.dp,\n    val xxxl: dp = 48.dp\n)\n\nval LocalSpacing = compositionLocalOf { Spacing() }\n\n// ==================== CUSTOM DIMENSIONS ====================\ndata class Dimensions(\n    val cardHeight: dp = 144.dp,\n    val countryCardHeight: dp = 200.dp,\n    val iconLarge: dp = 64.dp,\n    val iconMedium: dp = 32.dp,\n    val iconSmall: dp = 24.dp,\n    val buttonLarge: dp = 64.dp,\n    val buttonMedium: dp = 56.dp,\n    val buttonSmall: dp = 48.dp,\n    val cornerRadiusSmall: dp = 8.dp,\n    val cornerRadiusMedium: dp = 12.dp,\n    val cornerRadiusLarge: dp = 16.dp,\n    val focusRingWidth: dp = 4.dp\n)\n\nval LocalDimensions = compositionLocalOf { Dimensions() }\n\n// ==================== TYPOGRAPHY ====================\nval IPTVTypography = Typography(\n    displayLarge = TextStyle(\n        fontSize = 36.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 43.sp,\n        letterSpacing = (-1.5).sp\n    ),\n    displayMedium = TextStyle(\n        fontSize = 28.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 34.sp,\n        letterSpacing = 0.sp\n    ),\n    displaySmall = TextStyle(\n        fontSize = 22.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 26.sp,\n        letterSpacing = 0.sp\n    ),\n    headlineLarge = TextStyle(\n        fontSize = 28.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 34.sp,\n        letterSpacing = 0.sp\n    ),\n    headlineMedium = TextStyle(\n        fontSize = 24.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 29.sp,\n        letterSpacing = 0.sp\n    ),\n    headlineSmall = TextStyle(\n        fontSize = 20.sp,\n        fontWeight = FontWeight.SemiBold,\n        lineHeight = 24.sp,\n        letterSpacing = 0.sp\n    ),\n    titleLarge = TextStyle(\n        fontSize = 18.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 22.sp,\n        letterSpacing = 0.sp\n    ),\n    titleMedium = TextStyle(\n        fontSize = 16.sp,\n        fontWeight = FontWeight.SemiBold,\n        lineHeight = 19.sp,\n        letterSpacing = 0.1.sp\n    ),\n    titleSmall = TextStyle(\n        fontSize = 14.sp,\n        fontWeight = FontWeight.SemiBold,\n        lineHeight = 17.sp,\n        letterSpacing = 0.1.sp\n    ),\n    bodyLarge = TextStyle(\n        fontSize = 16.sp,\n        fontWeight = FontWeight.Normal,\n        lineHeight = 24.sp,\n        letterSpacing = 0.5.sp\n    ),\n    bodyMedium = TextStyle(\n        fontSize = 14.sp,\n        fontWeight = FontWeight.Normal,\n        lineHeight = 21.sp,\n        letterSpacing = 0.25.sp\n    ),\n    bodySmall = TextStyle(\n        fontSize = 12.sp,\n        fontWeight = FontWeight.Normal,\n        lineHeight = 18.sp,\n        letterSpacing = 0.4.sp\n    ),\n    labelLarge = TextStyle(\n        fontSize = 14.sp,\n        fontWeight = FontWeight.Bold,\n        lineHeight = 17.sp,\n        letterSpacing = 0.1.sp\n    ),\n    labelMedium = TextStyle(\n        fontSize = 12.sp,\n        fontWeight = FontWeight.SemiBold,\n        lineHeight = 14.sp,\n        letterSpacing = 0.5.sp\n    ),\n    labelSmall = TextStyle(\n        fontSize = 11.sp,\n        fontWeight = FontWeight.SemiBold,\n        lineHeight = 13.sp,\n        letterSpacing = 0.5.sp\n    )\n)\n\n// ==================== SHAPES ====================\nval IPTVShapes = Shapes(\n    extraSmall = androidx.compose.foundation.shape.RoundedCornerShape(4.dp),\n    small = androidx.compose.foundation.shape.RoundedCornerShape(8.dp),\n    medium = androidx.compose.foundation.shape.RoundedCornerShape(12.dp),\n    large = androidx.compose.foundation.shape.RoundedCornerShape(16.dp),\n    extraLarge = androidx.compose.foundation.shape.RoundedCornerShape(20.dp)\n)\n\n// ==================== COLOR SCHEME ====================\nprivate val DarkColorScheme = ColorScheme(\n    primary = PrimaryDark,\n    onPrimary = PrimaryForeground,\n    primaryContainer = Secondary,\n    onPrimaryContainer = SecondaryForeground,\n    secondary = Secondary,\n    onSecondary = SecondaryForeground,\n    secondaryContainer = Card,\n    onSecondaryContainer = Foreground,\n    tertiary = AccentYellow,\n    onTertiary = AccentYellowForeground,\n    tertiaryContainer = AccentBlue,\n    onTertiaryContainer = Color.White,\n    error = Error,\n    onError = Color.White,\n    errorContainer = Color(0xFF7F1D1D),\n    onErrorContainer = Color.White,\n    background = Background,\n    onBackground = Foreground,\n    surface = Card,\n    onSurface = Foreground,\n    surfaceVariant = Slate800,\n    onSurfaceVariant = Slate300,\n    outline = Border,\n    outlineVariant = Slate700,\n    scrim = Color.Black\n)\n\n// ==================== MAIN THEME COMPOSABLE ====================\n@Composable\nfun IPTVAppTheme(\n    darkTheme: Boolean = isSystemInDarkMode(),\n    // Dynamic color is available on Android 12+\n    dynamicColor: Boolean = false,\n    content: @Composable () -> Unit\n) {\n    val colorScheme = DarkColorScheme  // Always use dark theme for TV\n\n    CompositionLocalProvider(\n        LocalSpacing provides Spacing(),\n        LocalDimensions provides Dimensions()\n    ) {\n        MaterialTheme(\n            colorScheme = colorScheme,\n            typography = IPTVTypography,\n            shapes = IPTVShapes,\n            content = content\n        )\n    }\n}\n\n// ==================== ELEVATION SYSTEM ====================\nobject Elevations {\n    val level0 = 0.dp\n    val level1 = 1.dp\n    val level2 = 3.dp\n    val level3 = 6.dp\n    val level4 = 8.dp\n    val level5 = 12.dp\n}\n\n// ==================== ANIMATION DURATIONS ====================\nobject AnimationDurations {\n    const val FAST = 150  // Hover effects (ms)\n    const val DEFAULT = 300  // Normal transitions (ms)\n    const val SLOW = 500  // Page transitions (ms)\n}\n\n// ==================== FOCUS STATE HELPER ====================\ndata class FocusColors(\n    val unfocusedBorder: Color = Border,\n    val unfocusedBackground: Color = Slate800,\n    val focusedBorder: Color = AccentYellow,\n    val focusedBackground: Color = Slate700,\n    val focusedGlowColor: Color = AccentYellow\n)\n\nval DefaultFocusColors = FocusColors()\n\n// ==================== HELPER MODIFIERS ====================\nimport androidx.compose.foundation.border\nimport androidx.compose.foundation.shape.RoundedCornerShape\nimport androidx.compose.runtime.Modifier\nimport androidx.compose.ui.Modifier as ComposeModifier\n\n/**\n * Apply focused card styling\n */\nfun Modifier.focusedCardStyle(\n    isFocused: Boolean = false,\n    focusColors: FocusColors = DefaultFocusColors,\n    cornerRadius: dp = 16.dp\n): Modifier {\n    return this\n        .background(\n            color = if (isFocused) focusColors.focusedBackground else focusColors.unfocusedBackground,\n            shape = RoundedCornerShape(cornerRadius)\n        )\n        .border(\n            width = if (isFocused) 4.dp else 2.dp,\n            color = if (isFocused) focusColors.focusedBorder else focusColors.unfocusedBorder,\n            shape = RoundedCornerShape(cornerRadius)\n        )\n}\n\n/**\n * Apply quality badge styling\n */\nfun Modifier.qualityBadgeStyle(quality: String): Modifier {\n    val (backgroundColor, textColor) = getQualityBadgeColors(quality)\n    return this.background(\n        color = backgroundColor,\n        shape = RoundedCornerShape(8.dp)\n    )\n}\n"
}
